cat > 'scripts/deploy_agent.py' <<'QSAR_FILE_22_EOF'
"""Create the optional Cortex Agent from its versioned YAML specification."""

import argparse
from pathlib import Path

import snowflake.connector


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--connection", required=True, help="Snowflake CLI connection name")
    args = parser.parse_args()

    specification = (Path(__file__).resolve().parents[1] / "agent" / "aromatase_agent.yaml").read_text()
    # Reject a malformed closing delimiter rather than interpolating SQL from YAML.
    if "$$" in specification:
        raise ValueError("Agent specification cannot contain a SQL dollar delimiter")

    with snowflake.connector.connect(connection_name=args.connection) as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                "CREATE OR REPLACE AGENT QSAR_DB.PUBLIC.AROMATASE_AGENT "
                f"FROM SPECIFICATION $$\n{specification}\n$$"
            )
            print(cursor.fetchone()[0])
            cursor.execute(
                "GRANT USAGE ON AGENT QSAR_DB.PUBLIC.AROMATASE_AGENT TO ROLE QSAR_ROLE"
            )
            print(cursor.fetchone()[0])
            cursor.execute(
                "ALTER SNOWFLAKE INTELLIGENCE SNOWFLAKE_INTELLIGENCE_OBJECT_DEFAULT "
                "ADD AGENT QSAR_DB.PUBLIC.AROMATASE_AGENT"
            )
            print(cursor.fetchone()[0])


if __name__ == "__main__":
    main()
QSAR_FILE_22_EOF

cat > 'scripts/generate_dashboard_data.py' <<'QSAR_FILE_23_EOF'
#!/usr/bin/env python3
"""
Generate dashboard data files from ChEMBL1978 compounds and upload to Snowflake stage.

Produces:
  dashboard_eda.csv         pIC50 distribution + activity label per compound
  dashboard_ro5.csv         Lipinski Ro5 properties per compound
  dashboard_predictions.csv actual vs predicted pIC50 (batch inference via Plumber)

Usage:
  cd /path/to/bioinformatics/r-python-drug-discovery
  python scripts/generate_dashboard_data.py
"""

import os, sys, json, time, tempfile
import requests
import pandas as pd
import snowflake.connector
import toml, pathlib

# ── Config ────────────────────────────────────────────────────────────────────
PROJECT_ROOT   = pathlib.Path(__file__).parent.parent
CLEANED_CSV    = PROJECT_ROOT / "data" / "chembl1978_cleaned.csv"
# Public ingress URL from: SHOW ENDPOINTS IN SERVICE QSAR_DB.PUBLIC.QSAR_PLUMBER_SVC
_ENDPOINT      = os.environ["QSAR_ENDPOINT"].rstrip("/")
if not _ENDPOINT.startswith("http"):
    _ENDPOINT = "https://" + _ENDPOINT
PREDICT_URL    = _ENDPOINT + "/predict"
BATCH_SIZE     = 50   # compounds per /predict call
STAGE          = os.environ.get("QSAR_STAGE", "@QSAR_DB.PUBLIC.QSAR_STAGE")

# ── Snowflake auth ─────────────────────────────────────────────────────────────
CONNECTION     = os.environ.get("SNOWFLAKE_CONNECTION", "default")

def get_conn():
    # Uses a named connection from ~/.snowflake/connections.toml
    return snowflake.connector.connect(connection_name=CONNECTION)

# ── Load source data ───────────────────────────────────────────────────────────
print(f"Loading {CLEANED_CSV} ...")
df = pd.read_csv(CLEANED_CSV)
df = df.rename(columns={
    "pchembl_value":    "pchembl_value",
    "activity_class":   "activity_class",
    "canonical_smiles": "canonical_smiles",
})
df["activity_label"] = df["activity_class"].map({1: "Active", 0: "Inactive"})
print(f"  {len(df)} compounds loaded")

# ══════════════════════════════════════════════════════════════════════════════
# 1. EDA data
# ══════════════════════════════════════════════════════════════════════════════
print("\n[1/3] Generating EDA data ...")
eda_df = df[["pchembl_value", "activity_label"]].copy()
eda_df.columns = ["pchembl_value", "activity_label"]
print(f"  {len(eda_df)} rows")

# ══════════════════════════════════════════════════════════════════════════════
# 2. Ro5 properties (rdkit)
# ══════════════════════════════════════════════════════════════════════════════
print("\n[2/3] Computing Ro5 properties with rdkit ...")
try:
    from rdkit import Chem
    from rdkit.Chem import Descriptors, rdMolDescriptors, Crippen
except ImportError:
    print("  ERROR: rdkit not installed. Run: pip install rdkit-pypi")
    sys.exit(1)

rows = []
n_invalid = 0
for _, row in df.iterrows():
    mol = Chem.MolFromSmiles(row["canonical_smiles"])
    if mol is None:
        n_invalid += 1
        continue
    rows.append({
        "pchembl_value":  row["pchembl_value"],
        "mw":             round(Descriptors.MolWt(mol), 2),
        "logp":           round(Crippen.MolLogP(mol), 3),
        "hbd":            rdMolDescriptors.CalcNumHBD(mol),
        "hba":            rdMolDescriptors.CalcNumHBA(mol),
        "tpsa":           round(Descriptors.TPSA(mol), 2),
        "activity_label": row["activity_label"],
    })

ro5_df = pd.DataFrame(rows)
print(f"  {len(ro5_df)} valid molecules  ({n_invalid} skipped)")

# ══════════════════════════════════════════════════════════════════════════════
# 3. Actual vs predicted (batch inference through deployed Plumber service)
# ══════════════════════════════════════════════════════════════════════════════
print(f"\n[3/3] Running {len(df)} SMILES through Plumber /predict (batch={BATCH_SIZE}) ...")

# Public ingress requires a programmatic access token (PAT)
PAT = os.environ["SNOWFLAKE_PAT"]
headers = {
    "Content-Type":  "application/json",
    "Authorization": f"Snowflake Token=\"{PAT}\"",
}

smiles_list  = df["canonical_smiles"].tolist()
actual_list  = df["pchembl_value"].tolist()
pred_list    = []
failed_idx   = set()

for start in range(0, len(smiles_list), BATCH_SIZE):
    batch = smiles_list[start : start + BATCH_SIZE]
    payload = {"data": [[i, s] for i, s in enumerate(batch)]}
    for attempt in range(3):
        try:
            r = requests.post(PREDICT_URL, headers=headers, json=payload, timeout=120)
            r.raise_for_status()
            data = r.json().get("data", [])
            # data rows: [idx, pic50, activity, ci_lo, ci_hi]
            if (len(data) != len(batch) or
                    sorted(row[0] for row in data) != list(range(len(batch))) or
                    any(len(row) < 5 or not isinstance(row[1], (int, float)) for row in data)):
                raise ValueError("Incomplete or malformed prediction batch")
            data_sorted = sorted(data, key=lambda x: x[0])
            pred_list.extend([row[1] for row in data_sorted])
            break
        except Exception as e:
            if attempt == 2:
                print(f"  WARN: batch {start}-{start+len(batch)} failed: {e}")
                for i in range(len(batch)):
                    failed_idx.add(start + i)
                pred_list.extend([None] * len(batch))
            else:
                time.sleep(2)

    pct = min(100, round(100 * (start + len(batch)) / len(smiles_list)))
    print(f"  {pct:3d}%  ({start + len(batch)}/{len(smiles_list)})", end="\r")

print()

# Drop rows where prediction failed
pred_df = pd.DataFrame({
    "actual_pic50": actual_list,
    "pred_pic50":   pred_list,
    "activity_label": df["activity_label"].tolist(),
})
pred_df = pred_df.dropna(subset=["pred_pic50"]).reset_index(drop=True)
pred_df["pred_pic50"] = pred_df["pred_pic50"].round(3)
print(f"  {len(pred_df)} predictions  ({len(df) - len(pred_df)} failed)")

# ══════════════════════════════════════════════════════════════════════════════
# 4. Save to /tmp and upload to stage
# ══════════════════════════════════════════════════════════════════════════════
tmpdir = tempfile.mkdtemp()

files = {
    "dashboard_eda.csv":         eda_df,
    "dashboard_ro5.csv":         ro5_df,
    "dashboard_predictions.csv": pred_df,
}

print(f"\nSaving to {tmpdir} ...")
for fname, frame in files.items():
    fpath = os.path.join(tmpdir, fname)
    frame.to_csv(fpath, index=False)
    print(f"  {fname}  ({len(frame)} rows, {os.path.getsize(fpath)//1024} KB)")

print(f"\nUploading to {STAGE} ...")
conn = get_conn()
cur  = conn.cursor()
for fname in files:
    fpath = os.path.join(tmpdir, fname)
    cur.execute(
        f"PUT file://{fpath} {STAGE} AUTO_COMPRESS=FALSE OVERWRITE=TRUE"
    )
    print(f"  Uploaded: {fname}")
conn.close()

print(f"\nDone — confirm with: LIST {STAGE}")
QSAR_FILE_23_EOF

cat > 'scripts/test_endpoint.py' <<'QSAR_FILE_24_EOF'
"""
Smoke-test the AromatasePred R Plumber service through its public endpoint.

Usage:
    export QSAR_ENDPOINT="https://<your-ingress-url>"
    export SNOWFLAKE_PAT="<programmatic access token>"
    python scripts/test_endpoint.py

Get QSAR_ENDPOINT from: SHOW ENDPOINTS IN SERVICE QSAR_DB.PUBLIC.QSAR_PLUMBER_SVC
"""

import os

import requests

URL = os.environ["QSAR_ENDPOINT"].rstrip("/")
if not URL.startswith("http"):
    URL = "https://" + URL

# Public ingress expects the PAT in this exact form; "Bearer <pat>" redirects to sign-in.
HEADERS = {
    "Authorization": f'Snowflake Token="{os.environ["SNOWFLAKE_PAT"]}"',
    "Content-Type": "application/json",
}

COMPOUNDS = {
    "letrozole":   "N#Cc1ccc(cc1)C(n1cncn1)c1ccc(C#N)cc1",
    "anastrozole": "CC(C)(C#N)c1cc(Cn2cncn2)cc(c1)C(C)(C)C#N",
    "exemestane":  "C[C@]12CC[C@H]3[C@@H](CC(=C)C4=CC(=O)C=C[C@]34C)[C@@H]1CCC2=O",
    "ethanol":     "CCO",
    "invalid":     "not_a_smiles",
}

# ── Health ────────────────────────────────────────────────────────────────────
r = requests.get(f"{URL}/health", headers=HEADERS, timeout=60, allow_redirects=False)
print("health:", r.status_code, r.text)
r.raise_for_status()

# ── Batch prediction (Snowflake service-function row format) ─────────────────
names = list(COMPOUNDS)
payload = {"data": [[i, COMPOUNDS[n]] for i, n in enumerate(names)]}
r = requests.post(f"{URL}/predict", headers=HEADERS, json=payload, timeout=120)
r.raise_for_status()
print(f"\n{'compound':<12} {'pIC50':>6}  {'class':<10} {'q05':>5} {'q95':>5}")
for idx, pic50, label, lo, hi in r.json()["data"]:
    fmt = lambda v: f"{v:.2f}" if isinstance(v, (int, float)) else "-"
    print(f"{names[idx]:<12} {fmt(pic50):>6}  {str(label)[:30]:<10} {fmt(lo):>5} {fmt(hi):>5}")

# ── MCP (JSON-RPC 2.0) ────────────────────────────────────────────────────────
r = requests.post(f"{URL}/mcp", headers=HEADERS, timeout=120,
                  json={"jsonrpc": "2.0", "id": 1, "method": "tools/list"})
r.raise_for_status()
print("\nMCP tools:", [t["name"] for t in r.json()["result"]["tools"]])

r = requests.post(f"{URL}/mcp", headers=HEADERS, timeout=120,
                  json={"jsonrpc": "2.0", "id": 2, "method": "tools/call",
                        "params": {"name": "predict_pic50",
                                   "arguments": {"smiles": COMPOUNDS["letrozole"]}}})
r.raise_for_status()
print("\nMCP predict_pic50:\n" + r.json()["result"]["content"][0]["text"])
QSAR_FILE_24_EOF

cat > 'sql/agent.sql' <<'QSAR_FILE_25_EOF'
-- Optional Aromatase analyst. Run after notebooks 01 and 02 and functions.sql.
USE ROLE QSAR_ROLE;
USE WAREHOUSE QSAR_WH;
USE SCHEMA QSAR_DB.PUBLIC;

-- Create AROMATASE_SV from the Apache Ossie 0.1.1 specification (agent/aromatase_sv_ossie.yaml)
CALL SYSTEM$CREATE_SEMANTIC_VIEW_FROM_OSSIE_YAML('QSAR_DB.PUBLIC', $$
version: 0.1.1
semantic_model:
  - name: AROMATASE_SV
    description: "Measured human aromatase bioactivity and model scores; compound grain, one selected assay per compound. Training and test rows are mixed."
    datasets:
      - name: ASSAYS
        source: QSAR_DB.PUBLIC.CHEMBL1978_ASSAYS
        primary_key:
          - ASSAY_CHEMBL_ID
        fields:
          - name: ASSAY_DESCRIPTION
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: assays.DESCRIPTION
            dimension: {}
          - name: ASSAY_ID
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: assays.ASSAY_CHEMBL_ID
            dimension: {}
          - name: ASSAY_TYPE
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: assays.ASSAY_TYPE
            dimension: {}
      - name: COMPOUNDS
        source: QSAR_DB.PUBLIC.CHEMBL1978_COMPOUNDS
        primary_key:
          - MOLECULE_CHEMBL_ID
        fields:
          - name: ACTIVITY_LABEL
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: CASE WHEN compounds.ACTIVITY_CLASS = 1 THEN 'Active' ELSE 'Inactive' END
            dimension: {}
          - name: MOLECULE_ID
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: compounds.MOLECULE_CHEMBL_ID
            dimension: {}
          - name: SMILES
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: compounds.CANONICAL_SMILES
            dimension: {}
          - name: ACTIVE_FLAG
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: compounds.ACTIVITY_CLASS
          - name: MEASURED_PIC50
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: compounds.PCHEMBL_VALUE
      - name: DESCRIPTORS
        source: QSAR_DB.PUBLIC.CHEMBL1978_DESCRIPTORS
        primary_key:
          - MOLECULE_CHEMBL_ID
        fields:
          - name: RO5_PASS
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: descriptors.RO5_PASS
            dimension: {}
          - name: HBA
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: descriptors.HBA
          - name: HBD
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: descriptors.HBD
          - name: LOGP
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: descriptors.LOGP
          - name: MOLECULAR_WEIGHT
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: descriptors.MW
          - name: RO5_VIOLATIONS
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: descriptors.RO5_VIOLATIONS
          - name: TPSA
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: descriptors.TPSA
      - name: DOCUMENTS
        source: QSAR_DB.PUBLIC.CHEMBL1978_DOCUMENTS
        primary_key:
          - DOCUMENT_CHEMBL_ID
        fields:
          - name: DOCUMENT_ID
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: documents.DOCUMENT_CHEMBL_ID
            dimension: {}
          - name: JOURNAL
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: documents.JOURNAL
            dimension: {}
          - name: PUBLICATION_YEAR
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: TRY_TO_NUMBER(documents.YEAR)
            dimension: {}
          - name: TITLE
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: documents.TITLE
            dimension: {}
      - name: FINGERPRINTS
        source: QSAR_DB.PUBLIC.CHEMBL1978_FINGERPRINTS
        primary_key:
          - MOLECULE_CHEMBL_ID
        fields:
          - name: BIT_COUNT
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: ARRAY_SIZE(fingerprints.ECFP4_BITS)
      - name: PREDICTIONS
        source: QSAR_DB.PUBLIC.CHEMBL1978_PREDICTIONS
        primary_key:
          - MOLECULE_CHEMBL_ID
        fields:
          - name: PREDICTED_PIC50
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: predictions.PRED_PIC50
          - name: PREDICTION_ERROR
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: predictions.ERROR
      - name: PREDICTION_LOG
        source: QSAR_DB.PUBLIC.QSAR_PREDICTIONS_LOG
        primary_key:
          - PREDICTION_ID
        fields:
          - name: PREDICTED_AT
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: prediction_log.PREDICTED_AT
            dimension: {}
          - name: SERVICE_USER
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: prediction_log.USER_NAME
            dimension: {}
          - name: PREDICTED_PIC50
            expression:
              dialects:
                - dialect: SNOWFLAKE
                  expression: prediction_log.PREDICTED_PIC50
    relationships:
      - name: ASSAYS_TO_DOCUMENTS
        from: ASSAYS
        to: DOCUMENTS
        from_columns:
          - DOCUMENT_CHEMBL_ID
        to_columns:
          - DOCUMENT_CHEMBL_ID
      - name: COMPOUNDS_TO_ASSAYS
        from: COMPOUNDS
        to: ASSAYS
        from_columns:
          - ASSAY_CHEMBL_ID
        to_columns:
          - ASSAY_CHEMBL_ID
      - name: DESCRIPTORS_TO_COMPOUNDS
        from: DESCRIPTORS
        to: COMPOUNDS
        from_columns:
          - MOLECULE_CHEMBL_ID
        to_columns:
          - MOLECULE_CHEMBL_ID
      - name: FINGERPRINTS_TO_COMPOUNDS
        from: FINGERPRINTS
        to: COMPOUNDS
        from_columns:
          - MOLECULE_CHEMBL_ID
        to_columns:
          - MOLECULE_CHEMBL_ID
      - name: PREDICTIONS_TO_COMPOUNDS
        from: PREDICTIONS
        to: COMPOUNDS
        from_columns:
          - MOLECULE_CHEMBL_ID
        to_columns:
          - MOLECULE_CHEMBL_ID
    metrics:
      - name: compound_count
        expression:
          dialects:
            - dialect: SNOWFLAKE
              expression: COUNT(compounds.molecule_id)
        description: Total number of deduplicated aromatase compounds
      - name: active_count
        expression:
          dialects:
            - dialect: SNOWFLAKE
              expression: SUM(compounds.active_flag)
        description: Number of measured active compounds (pIC50 >= 6.5)
      - name: mean_measured_pic50
        expression:
          dialects:
            - dialect: SNOWFLAKE
              expression: AVG(compounds.measured_pic50)
        description: Mean measured pIC50 across compounds
      - name: mean_predicted_pic50
        expression:
          dialects:
            - dialect: SNOWFLAKE
              expression: AVG(predictions.predicted_pic50)
        description: Mean predicted pIC50 from the R QSAR model
      - name: rmse
        expression:
          dialects:
            - dialect: SNOWFLAKE
              expression: SQRT(AVG(POWER(predictions.prediction_error, 2)))
        description: Root mean squared error across scored compounds
      - name: ro5_pass_count
        expression:
          dialects:
            - dialect: SNOWFLAKE
              expression: COUNT_IF(descriptors.ro5_pass)
        description: Number of compounds passing Lipinski's Rule of Five
      - name: mean_bits_on
        expression:
          dialects:
            - dialect: SNOWFLAKE
              expression: AVG(fingerprints.bit_count)
        description: Mean number of active ECFP4 bits per molecule
      - name: request_count
        expression:
          dialects:
            - dialect: SNOWFLAKE
              expression: COUNT(prediction_log.predicted_at)
        description: Total logged prediction requests
    custom_extensions:
      - vendor_name: SNOWFLAKE
        data: '{"verified_queries":[{"name":"COMPOUND_TOTALS","sql":"SELECT * FROM SEMANTIC_VIEW(QSAR_DB.PUBLIC.AROMATASE_SV METRICS compound_count, active_count)","question":"How many compounds and actives are in the aromatase dataset?","use_as_onboarding_question":true},{"name":"ACTIVITY_BREAKDOWN","sql":"SELECT * FROM SEMANTIC_VIEW(QSAR_DB.PUBLIC.AROMATASE_SV DIMENSIONS compounds.activity_label METRICS compound_count)","question":"How many active and inactive aromatase compounds are there?"},{"name":"RO5_TOTAL","sql":"SELECT * FROM SEMANTIC_VIEW(QSAR_DB.PUBLIC.AROMATASE_SV METRICS ro5_pass_count)","question":"How many compounds pass the Rule of Five?"}]}'
$$);

-- One search row per measured molecule and assay. Repeated raw measurements
-- for the same molecule, assay and document are deduplicated by SELECT DISTINCT.
CREATE OR REPLACE CORTEX SEARCH SERVICE ASSAY_SEARCH
  ON SEARCH_TEXT
  ATTRIBUTES MOLECULE_CHEMBL_ID, ASSAY_CHEMBL_ID, DOCUMENT_CHEMBL_ID
  WAREHOUSE = QSAR_WH
  TARGET_LAG = '1 day'
  AS
  SELECT DISTINCT
    r.MOLECULE_CHEMBL_ID,
    r.ASSAY_CHEMBL_ID,
    a.DOCUMENT_CHEMBL_ID,
    CONCAT_WS(' | ', 'Assay ID: ' || r.ASSAY_CHEMBL_ID,
              'Publication ID: ' || COALESCE(a.DOCUMENT_CHEMBL_ID, 'unknown'),
              COALESCE(a.DESCRIPTION, ''), COALESCE(d.TITLE, ''),
              COALESCE(d.ABSTRACT, ''), COALESCE(d.JOURNAL, '')) AS SEARCH_TEXT
  FROM CHEMBL1978_RAW_ACTIVITIES r
  JOIN CHEMBL1978_ASSAYS a ON r.ASSAY_CHEMBL_ID = a.ASSAY_CHEMBL_ID
  LEFT JOIN CHEMBL1978_DOCUMENTS d ON a.DOCUMENT_CHEMBL_ID = d.DOCUMENT_CHEMBL_ID;

-- One SMILES per line; the generic agent tool passes one string argument.
-- Novelty compares against all measured compounds (training and held-out rows).
-- It is a similarity heuristic, not a validated applicability domain.
CREATE OR REPLACE PROCEDURE TRIAGE_COMPOUNDS(smiles_list VARCHAR)
  RETURNS VARIANT
  LANGUAGE SQL
  EXECUTE AS OWNER
AS $$
DECLARE
  results ARRAY DEFAULT ARRAY_CONSTRUCT();
  input_rows ARRAY;
  entry VARCHAR;
  predicted VARIANT;
  nearest VARIANT;
  properties VARIANT;
  similarity FLOAT;
  ranking FLOAT;
  reason VARCHAR;
BEGIN
  input_rows := SPLIT(:smiles_list, '\n');
  IF (ARRAY_SIZE(:input_rows) > 20) THEN
    RETURN OBJECT_CONSTRUCT('error', 'At most 20 SMILES per request');
  END IF;
  FOR idx IN 0 TO ARRAY_SIZE(:input_rows) - 1 DO
    entry := TRIM(input_rows[idx]::VARCHAR);
    IF (entry <> '') THEN
      SELECT PREDICT_PIC50(:entry), SIMILAR_COMPOUNDS(:entry, 1), RO5(:entry)
        INTO :predicted, :nearest, :properties;
      IF (predicted:error IS NOT NULL OR properties:error IS NOT NULL) THEN
        results := ARRAY_APPEND(:results,
          OBJECT_CONSTRUCT('smiles', :entry, 'error', 'Invalid SMILES'));
      ELSE
        similarity := nearest:max_tanimoto::FLOAT;
        ranking := predicted:pic50::FLOAT - IFF(similarity < 0.4, 1.0, IFF(similarity < 0.6, 0.5, 0.0))
                   - 0.25 * properties:ro5_violations::INT;
        reason := IFF(similarity < 0.4, 'Low measured-set similarity (<0.4); uncertain extrapolation. ',
                     IFF(similarity < 0.6, 'Moderate measured-set similarity (0.4-0.6). ',
                         'High measured-set similarity (>=0.6). ')) ||
                  IFF(properties:ro5_pass::BOOLEAN, 'Passes Rule of Five.',
                      'Has multiple Rule-of-Five violations.');
        results := ARRAY_APPEND(:results, OBJECT_CONSTRUCT(
          'smiles', :entry, 'predicted_pic50', predicted:pic50,
          'predicted_class', predicted:activity,
          'q05', predicted:q05, 'q95', predicted:q95,
          'max_tanimoto', :similarity,
          'nearest_measured', nearest:neighbours[0],
          'ro5', :properties, 'triage_score', ROUND(:ranking, 3),
          'reason', :reason));
      END IF;
    END IF;
  END FOR;
  SELECT COALESCE(ARRAY_AGG(value) WITHIN GROUP (ORDER BY value:triage_score::FLOAT DESC NULLS LAST), ARRAY_CONSTRUCT())
    INTO :results FROM TABLE(FLATTEN(INPUT => :results));
  RETURN OBJECT_CONSTRUCT('ranked_compounds', :results,
    'note', 'Similarity uses all 2751 measured compounds including held-out rows. Prioritization heuristic, not a clinical decision or calibrated applicability domain. Ranges are uncalibrated model quantiles.');
END;
$$;

-- Create the agent from agent/aromatase_agent.yaml after the SQL above with
-- scripts/deploy_agent.py. The script also lists it in Snowflake Intelligence.
