cat > 'sql/functions.sql' <<'QSAR_FILE_26_EOF'
-- =============================================================================
-- AromatasePred: shared SQL function layer
--
-- Run after the R service QSAR_PLUMBER_SVC is READY. The four service functions
-- call the R Plumber container, so fingerprints, predictions, similarity, and
-- explanations all use the same rcdk ECFP4 code the model was trained with.
-- RO5() uses RDKit and matches the descriptors in dashboard_ro5.csv.
-- =============================================================================

USE ROLE QSAR_ROLE;
USE WAREHOUSE QSAR_WH;
USE SCHEMA QSAR_DB.PUBLIC;

-- ── 1. Service functions over the R service ─────────────────────────────────
-- Each returns an OBJECT; invalid SMILES return {"error": "..."}.

-- {"bits": [...], "n_bits_on": n}: 1-based ECFP4 bits, same as training
CREATE OR REPLACE FUNCTION ECFP4(smiles VARCHAR)
    RETURNS VARIANT
    STRICT
    SERVICE = QSAR_PLUMBER_SVC
    ENDPOINT = api
    MAX_BATCH_ROWS = 50
    AS '/sf/fingerprint';

-- {"pic50", "activity", "q05", "q95", "ic50_nm"}
CREATE OR REPLACE FUNCTION PREDICT_PIC50(smiles VARCHAR)
    RETURNS VARIANT
    STRICT
    SERVICE = QSAR_PLUMBER_SVC
    ENDPOINT = api
    MAX_BATCH_ROWS = 50
    AS '/sf/predict';

-- {"max_tanimoto", "neighbours": [{molecule_chembl_id, tanimoto, pchembl_value, activity_class, canonical_smiles}]}
CREATE OR REPLACE FUNCTION SIMILAR_COMPOUNDS(smiles VARCHAR, k INTEGER)
    RETURNS VARIANT
    STRICT
    SERVICE = QSAR_PLUMBER_SVC
    ENDPOINT = api
    MAX_BATCH_ROWS = 10
    AS '/sf/similar';

-- {"pic50", "activity", "n_present", "top_features": [{bit, importance_rank, importance, fragments, radius}]}
CREATE OR REPLACE FUNCTION EXPLAIN_PREDICTION(smiles VARCHAR, n INTEGER)
    RETURNS VARIANT
    STRICT
    SERVICE = QSAR_PLUMBER_SVC
    ENDPOINT = api
    MAX_BATCH_ROWS = 10
    AS '/sf/explain';

-- ── 2. Rule of Five descriptors (RDKit) ──────────────────────────────────────
-- Pinned to the RDKit version notebook 01 uses, installed from PyPI. Later
-- releases count hydrogen-bond acceptors differently for about 1,000 compounds.
CREATE OR REPLACE FUNCTION RO5(smiles VARCHAR)
    RETURNS VARIANT
    LANGUAGE PYTHON
    RUNTIME_VERSION = '3.11'
    ARTIFACT_REPOSITORY = snowflake.snowpark.pypi_shared_repository
    PACKAGES = ('rdkit==2025.09.3')
    HANDLER = 'ro5'
AS $$
from rdkit import Chem, RDLogger
from rdkit.Chem import Crippen, Descriptors, rdMolDescriptors

RDLogger.DisableLog("rdApp.*")


def ro5(smiles):
    mol = Chem.MolFromSmiles(smiles) if smiles else None
    if mol is None:
        return {"error": "Invalid SMILES"}
    mw = round(Descriptors.MolWt(mol), 2)
    logp = round(Crippen.MolLogP(mol), 3)
    hbd = rdMolDescriptors.CalcNumHBD(mol)
    hba = rdMolDescriptors.CalcNumHBA(mol)
    violations = (mw > 500) + (logp > 5) + (hbd > 5) + (hba > 10)
    return {"mw": mw, "logp": logp, "hbd": hbd, "hba": hba,
            "tpsa": round(Descriptors.TPSA(mol), 2),
            "ro5_violations": int(violations), "ro5_pass": violations <= 1}
$$;

-- ── 3. Checks ────────────────────────────────────────────────────────────────
-- Letrozole: pIC50 7.89 (bundled model), top feature bit_319 = triazole
SELECT PREDICT_PIC50('N#Cc1ccc(cc1)C(n1cncn1)c1ccc(C#N)cc1') AS prediction,
       RO5('N#Cc1ccc(cc1)C(n1cncn1)c1ccc(C#N)cc1')           AS ro5,
       EXPLAIN_PREDICTION('N#Cc1ccc(cc1)C(n1cncn1)c1ccc(C#N)cc1', 3):top_features AS top_features;
QSAR_FILE_26_EOF

cat > 'sql/setup.sql' <<'QSAR_FILE_27_EOF'
-- =============================================================================
-- AromatasePred: Snowflake setup for the R Plumber inference service
--
-- Run steps 1-2 as ACCOUNTADMIN, then switch to QSAR_ROLE for the rest.
-- Replace <your_user> before running.
-- =============================================================================

-- ── 1. Role, warehouse, database ─────────────────────────────────────────────
USE ROLE ACCOUNTADMIN;

CREATE ROLE IF NOT EXISTS QSAR_ROLE;
GRANT ROLE QSAR_ROLE TO USER <your_user>;
-- SYSADMIN (and so ACCOUNTADMIN) inherits QSAR_ROLE, so admin CLI connections can use its objects
GRANT ROLE QSAR_ROLE TO ROLE SYSADMIN;

CREATE WAREHOUSE IF NOT EXISTS QSAR_WH
    WAREHOUSE_SIZE = XSMALL
    AUTO_SUSPEND = 60
    AUTO_RESUME = TRUE;
GRANT USAGE ON WAREHOUSE QSAR_WH TO ROLE QSAR_ROLE;

CREATE DATABASE IF NOT EXISTS QSAR_DB;
GRANT OWNERSHIP ON DATABASE QSAR_DB TO ROLE QSAR_ROLE COPY CURRENT GRANTS;
GRANT OWNERSHIP ON SCHEMA QSAR_DB.PUBLIC TO ROLE QSAR_ROLE COPY CURRENT GRANTS;

-- ── 2. Compute pool and endpoint privilege ───────────────────────────────────
CREATE COMPUTE POOL IF NOT EXISTS QSAR_CPU_POOL
    MIN_NODES = 1
    MAX_NODES = 1
    INSTANCE_FAMILY = CPU_X64_S
    AUTO_RESUME = TRUE
    AUTO_SUSPEND_SECS = 3600
    COMMENT = 'QSAR aromatase SPCS inference';
GRANT USAGE, MONITOR ON COMPUTE POOL QSAR_CPU_POOL TO ROLE QSAR_ROLE;
GRANT BIND SERVICE ENDPOINT ON ACCOUNT TO ROLE QSAR_ROLE;
-- Lets the RO5() function in functions.sql install an exact RDKit version from PyPI
GRANT DATABASE ROLE SNOWFLAKE.PYPI_REPOSITORY_USER TO ROLE QSAR_ROLE;

-- Separate small pool for the Streamlit container runtime.
-- MAX_NODES = 2 leaves room for a new app instance while an old one shuts down.
CREATE COMPUTE POOL IF NOT EXISTS QSAR_ST_POOL
    MIN_NODES = 1
    MAX_NODES = 2
    INSTANCE_FAMILY = CPU_X64_XS
    AUTO_RESUME = TRUE
    AUTO_SUSPEND_SECS = 600
    COMMENT = 'Streamlit container runtime for the QSAR app';
GRANT USAGE, MONITOR ON COMPUTE POOL QSAR_ST_POOL TO ROLE QSAR_ROLE;

-- ── 3. Stage, image repository, audit table ──────────────────────────────────
USE ROLE QSAR_ROLE;
USE WAREHOUSE QSAR_WH;
USE SCHEMA QSAR_DB.PUBLIC;

CREATE STAGE IF NOT EXISTS QSAR_STAGE
    ENCRYPTION = (TYPE = 'SNOWFLAKE_SSE')
    COMMENT = 'Model metadata and dashboard CSVs for the Streamlit app';

CREATE IMAGE REPOSITORY IF NOT EXISTS QSAR_REPO
    COMMENT = 'R Plumber inference image';

-- repository_url column is the docker push target
SHOW IMAGE REPOSITORIES IN SCHEMA QSAR_DB.PUBLIC;

CREATE TABLE IF NOT EXISTS QSAR_PREDICTIONS_LOG (
    PREDICTION_ID    NUMBER AUTOINCREMENT START 1 INCREMENT 1 NOORDER,
    PREDICTED_AT     TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(),
    USER_NAME        VARCHAR(100) DEFAULT CURRENT_USER(),
    INPUT_SMILES     VARCHAR(4000) NOT NULL,
    PREDICTED_PIC50  FLOAT NOT NULL,
    ACTIVITY_CLASS   VARCHAR(10) NOT NULL,
    IC50_NM_APPROX   FLOAT,
    PRIMARY KEY (PREDICTION_ID)
)
COMMENT = 'Audit trail of predictions made from the Streamlit app';

-- ── 4. Egress for the Streamlit app ──────────────────────────────────────────
-- PyPI installs rdkit and streamlit-jsme; PubChem serves optional name and
-- structure-image lookups (this sends SMILES and InChIKeys outside Snowflake).
CREATE NETWORK RULE IF NOT EXISTS QSAR_APP_EGRESS
    TYPE = HOST_PORT
    MODE = EGRESS
    VALUE_LIST = ('pypi.org', 'files.pythonhosted.org', 'pubchem.ncbi.nlm.nih.gov');

USE ROLE ACCOUNTADMIN;
CREATE EXTERNAL ACCESS INTEGRATION IF NOT EXISTS QSAR_APP_EAI
    ALLOWED_NETWORK_RULES = (QSAR_DB.PUBLIC.QSAR_APP_EGRESS)
    ENABLED = TRUE;
GRANT USAGE ON INTEGRATION QSAR_APP_EAI TO ROLE QSAR_ROLE;

-- Egress for notebooks/01_prepare_training_data.ipynb (ChEMBL REST API and PyPI for RDKit)
-- and 02_score_compounds.ipynb. Both notebooks can run on QSAR_ST_POOL.
CREATE NETWORK RULE IF NOT EXISTS QSAR_DB.PUBLIC.QSAR_NB_EGRESS
    TYPE = HOST_PORT
    MODE = EGRESS
    VALUE_LIST = ('www.ebi.ac.uk', 'pypi.org', 'files.pythonhosted.org');
CREATE EXTERNAL ACCESS INTEGRATION IF NOT EXISTS QSAR_NB_EAI
    ALLOWED_NETWORK_RULES = (QSAR_DB.PUBLIC.QSAR_NB_EGRESS)
    ENABLED = TRUE;
GRANT USAGE ON INTEGRATION QSAR_NB_EAI TO ROLE QSAR_ROLE;
USE ROLE QSAR_ROLE;

-- ── 5. Inference service (run after pushing the image) ───────────────────────
-- CREATE SERVICE QSAR_PLUMBER_SVC
--     IN COMPUTE POOL QSAR_CPU_POOL
--     FROM SPECIFICATION $$
--     <contents of docker/plumber_spec.yaml>
--     $$
--     MIN_INSTANCES = 1
--     MAX_INSTANCES = 1;
--
-- SHOW SERVICE CONTAINERS IN SERVICE QSAR_PLUMBER_SVC;
-- SHOW ENDPOINTS IN SERVICE QSAR_PLUMBER_SVC;
QSAR_FILE_27_EOF

cat > 'streamlit/_shared.py' <<'QSAR_FILE_28_EOF'
"""Shared utilities, constants, and cached data-loading functions."""

import json
import os
import math
import tempfile
from io import BytesIO

import requests
import pandas as pd
import streamlit as st
from rdkit import Chem
from rdkit.Chem import rdDepictor

try:
    from rdkit.Chem import Draw as RDKitDraw
    _RDKIT_DRAW = True
except (ImportError, OSError):
    _RDKIT_DRAW = False

from rdkit.Chem.inchi import MolToInchi, InchiToInchiKey

# ── Constants ─────────────────────────────────────────────────────────────────
# Database and schema holding the stage and audit table; change if you used other names
_DB_SCHEMA = "QSAR_DB.PUBLIC"
_STAGE = f"@{_DB_SCHEMA}.QSAR_STAGE"

EXAMPLES = {
    "FDA-approved — Letrozole (Femara)":     "N#Cc1ccc(cc1)C(n1cncn1)c1ccc(C#N)cc1",
    "FDA-approved — Anastrozole (Arimidex)": "CC(C)(C#N)c1cc(Cn2cncn2)cc(c1)C(C)(C)C#N",
    "FDA-approved — Exemestane (Aromasin)":  "C[C@]12CC[C@H]3[C@@H](CC(=C)C4=CC(=O)C=C[C@]34C)[C@@H]1CCC2=O",
    "Inactive — Aspirin":                    "CC(=O)Oc1ccccc1C(=O)O",
    "Inactive — Caffeine":                   "Cn1c(=O)c2c(ncn2C)n(C)c1=O",
}


def _secret(*path, default=None):
    """Read a nested Streamlit secret; Streamlit in Snowflake has no secrets.toml, so missing is normal."""
    try:
        node = st.secrets
        for key in path:
            node = node[key]
        return node
    except Exception:
        return default


def get_predict_url() -> str:
    """Use an explicit local URL or discover the in-account service endpoint."""
    configured = _secret("spcs", "predict_url")
    if configured:
        return configured
    if not running_in_snowflake():
        raise RuntimeError("Configure spcs.predict_url in Streamlit secrets for local use")
    session = init_session()
    services = session.sql(f"SHOW SERVICES LIKE 'QSAR_PLUMBER_SVC' IN SCHEMA {_DB_SCHEMA}").collect()
    if not services:
        raise RuntimeError(f"QSAR_PLUMBER_SVC not found in {_DB_SCHEMA}")
    dns_name = services[0].as_dict().get("dns_name")
    if not dns_name:
        raise RuntimeError("Service DNS name is unavailable; configure spcs.predict_url")
    return f"http://{dns_name}:5000/predict"


def get_spcs_token() -> str:
    # Only needed when calling the public ingress URL from outside Snowflake
    return _secret("spcs", "token") or _secret("connections", "snowflake", "password", default="")


@st.cache_resource
def running_in_snowflake() -> bool:
    """True inside Streamlit in Snowflake, where an active Snowpark session is provided."""
    try:
        from snowflake.snowpark.context import get_active_session
        get_active_session()
        return True
    except Exception:
        return False


def _create_session():
    try:
        from snowflake.snowpark.context import get_active_session
        st.session_state._sf_session = get_active_session()
    except Exception:
        st.session_state._sf_session = st.connection("snowflake").session()


def init_session():
    """Create (or recreate) the Snowflake session; validates liveness on each call."""
    if "_sf_session" not in st.session_state:
        _create_session()
    else:
        # Validate that the cached session is still alive; reconnect if not.
        try:
            st.session_state._sf_session.sql("SELECT 1").collect()
        except Exception:
            del st.session_state._sf_session
            _create_session()
    return st.session_state._sf_session


# ── Chemistry helpers ─────────────────────────────────────────────────────────

def smiles_to_image(smiles: str, allow_external: bool = False):
    """Render locally with RDKit; only use PubChem fallback with explicit opt-in."""
    mol = Chem.MolFromSmiles(smiles)
    if mol is None:
        return None
    if _RDKIT_DRAW:
        try:
            rdDepictor.Compute2DCoords(mol)
            img = RDKitDraw.MolToImage(mol, size=(400, 300))
            buf = BytesIO()
            img.save(buf, format="PNG")
            return buf.getvalue()
        except Exception:
            pass
    if not allow_external:
        return None
    try:
        resp = requests.get(
            "https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/smiles/PNG",
            params={"smiles": smiles},
            timeout=10,
        )
        if resp.status_code == 200:
            return resp.content
    except Exception:
        pass
    return None


def smiles_to_names(smiles: str) -> dict:
    """Return {'iupac': str|None, 'common': str|None} via RDKit InChIKey → PubChem."""
    result = {"iupac": None, "common": None}
    try:
        mol = Chem.MolFromSmiles(smiles)
        if mol is None:
            return result
        inchikey = InchiToInchiKey(MolToInchi(mol))
        resp = requests.get(
            f"https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/inchikey/{inchikey}/property/IUPACName,Title/JSON",
            timeout=10,
        )
        if resp.status_code == 200:
            props = resp.json()["PropertyTable"]["Properties"][0]
            result["iupac"]  = props.get("IUPACName") or None
            result["common"] = props.get("Title") or None
    except Exception:
        pass
    return result


# ── Inference ─────────────────────────────────────────────────────────────────

def predict_pic50(smiles: str) -> dict | None:
    try:
        token = get_spcs_token()
        headers = {"Content-Type": "application/json"}
        if token:
            headers["Authorization"] = f'Snowflake Token="{token}"'
        resp = requests.post(
            get_predict_url(),
            headers=headers,
            json={"data": [[0, smiles]]},
            timeout=60,
        )
        resp.raise_for_status()
        rows = resp.json().get("data", [])
        if not rows:
            st.error("Service returned no results.")
            return None
        _, pic50, activity, ci_lo, ci_hi = rows[0]
        _activity = str(activity)
        if _activity == "Borderline":
            _activity = "Intermediate"
        return {
            "pic50":    float(pic50),
            "activity": _activity,
            "ci_lo":    float(ci_lo) if ci_lo is not None else None,
            "ci_hi":    float(ci_hi) if ci_hi is not None else None,
        }
    except requests.exceptions.ConnectionError:
        st.error("Cannot reach inference service — it may still be starting up. Wait ~2 minutes and try again.")
        return None
    except requests.exceptions.HTTPError as e:
        st.error(f"Service error {e.response.status_code}: {e.response.text[:200]}")
        return None
    except Exception as e:
        st.error(f"Prediction error: {e}")
        return None


def log_prediction(smiles: str, pred: dict):
    session = st.session_state.get("_sf_session")
    if session is None:
        return
    safe_smiles = smiles.replace("'", "''").replace("\\", "")[:4000]
    try:
        session.sql(
            f"INSERT INTO {_DB_SCHEMA}.QSAR_PREDICTIONS_LOG "
            f"(INPUT_SMILES, PREDICTED_PIC50, ACTIVITY_CLASS) "
            f"VALUES ('{safe_smiles}', {pred['pic50']:.6f}, '{pred['activity']}')"
        ).collect()
    except Exception:
        pass


# ── Stage / data loading ──────────────────────────────────────────────────────

def _stage_get(fname: str, tmpdir: str) -> str:
    session = st.session_state.get("_sf_session")
    if session is None:
        session = init_session()
    try:
        session.file.get(f"{_STAGE}/{fname}", tmpdir)
    except Exception:
        # Session expired — reconnect once and retry
        del st.session_state._sf_session
        session = init_session()
        session.file.get(f"{_STAGE}/{fname}", tmpdir)
    return os.path.join(tmpdir, fname)


@st.cache_data(ttl=3600)
def load_top_features():
    try:
        tmp = tempfile.mkdtemp()
        df = pd.read_csv(_stage_get("top_features.csv", tmp), header=0)
        df.columns = ["bit", "importance"]
        return df.head(20)
    except Exception as e:
        st.caption(f"Feature importance unavailable: {e}")
        return pd.DataFrame()


@st.cache_data(ttl=3600)
def load_metrics():
    try:
        tmp = tempfile.mkdtemp()
        with open(_stage_get("training_metrics.json", tmp)) as f:
            return json.load(f)
    except Exception as e:
        st.caption(f"Metrics unavailable: {e}")
        return {}


@st.cache_data(ttl=3600)
def load_eda():
    try:
        tmp = tempfile.mkdtemp()
        return pd.read_csv(_stage_get("dashboard_eda.csv", tmp))
    except Exception:
        return pd.DataFrame()


@st.cache_data(ttl=3600)
def load_ro5():
    try:
        tmp = tempfile.mkdtemp()
        df = pd.read_csv(_stage_get("dashboard_ro5.csv", tmp))
        return df  # v2: includes pchembl_value column
    except Exception:
        return pd.DataFrame()


@st.cache_data(ttl=3600)
def load_predictions():
    try:
        tmp = tempfile.mkdtemp()
        return pd.read_csv(_stage_get("dashboard_predictions.csv", tmp))
    except Exception:
        return pd.DataFrame()
